INSERT INTO "document" ("id", "kind", "numbering", "number", "sequence", "slug", "title", "status", "status_note", "parent_id", "parent_kind", "archived_at", "commit_sha", "created_at", "updated_at", "retro_waived_at", "retro_waived_reason") VALUES ('01M11RZ8SD3NYTSCV5C534NVPD', 'adr', 'child', NULL, 6, 'tracing-a-decision-warranted-criterion', 'How a criterion warranted by a decision becomes traceable', 'pending', 'Accepted with the lost rigour understood rather than discovered: a warrant carries no quoted fragment and no verification mark, so nothing decays it when the decision it names is amended. The binding-shaped alternative was rejected on the null paths it would open through machinery that already works, not on its rigour, and it is the option to revisit if warrants ever go stale in practice.', '01M11F97T7W9ZJVCTC1E1DQGJG', 'spec', NULL, NULL, '2026-08-27T14:11:22.029Z', '2026-08-27T14:12:08.129Z', NULL, NULL);
