INSERT INTO "document" ("id", "kind", "numbering", "number", "sequence", "slug", "title", "status", "status_note", "parent_id", "parent_kind", "archived_at", "commit_sha", "created_at", "updated_at", "retro_waived_at", "retro_waived_reason") VALUES ('01M11YAWNDK5QKGD07DB6VWJDC', 'epic', 'child', NULL, 2, 'retire-coverage', 'Retiring a binding', 'complete', 'Story 1 was superseded during the pivot and delivered as epic 04-01 story 4 — the write arm had to land with the column it reaches. The promise stands as kept; stories 2, 3 and 4 were delivered here. FR1 is left unclaimed: five coverage rows bound to story 1''s superseded criteria are still unverified, and retiring them needs retire_coverage, which this project''s database does not have until the plugin is reinstalled past schema 25.', '01M11F97T7W9ZJVCTC1E1DQGJG', 'spec', NULL, NULL, '2026-08-27T15:45:05.709Z', '2026-08-28T08:56:35.263Z', '2026-08-28T00:00:00Z', 'Reflected on at spec level rather than epic level: every observation this epic''s stories produced is gathered into retro 06, written on spec 04. There is nothing left to synthesise here, and an epic-level retro would restate what that one already says.');
