INSERT INTO "document" ("id", "kind", "numbering", "number", "sequence", "slug", "title", "status", "status_note", "parent_id", "parent_kind", "archived_at", "commit_sha", "created_at", "updated_at", "retro_waived_at", "retro_waived_reason") VALUES ('01M1XH3DPT5R6ZMN9N5HYEZ79X', 'quick', 'root', 12, NULL, 'plan-column-meaning-at-the-boundary', 'The plan column says what its values mean, where the run is handed them', 'complete', 'Closed with all seven criteria met. Criterion 1''s note records one imprecision in its own wording: `read_story` declares no `plan` property, so the gloss reaches a run through the create and update schemas rather than through the read response. The fix makes the correct sentence available and does not enforce it; the stronger candidate stays open in {{ref:01M1XG0J5FG91DRPCYNRR1BMDG}}.', NULL, NULL, NULL, NULL, '2026-09-07T08:52:33.626Z', '2026-09-07T08:56:30.297Z', NULL, NULL);
