INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M11ZNRY055EM70JPZNRV9Z5Q', '01M11YAYQW06A2KBRMHHYHZE27', 'epic', 2, 'The register names a retirement made while sound', 'complete', 'All five criteria verified, each with its mutation control run. Task 2 — attaching warrant_adr_id to the five criteria, naming accepted ADR 04-05 — is outstanding and blocked on the plugin reinstall: the warrant arm landed in this working tree as epic 04-01 story 5, and the server is the installed 0.6.0 release. Closed on Chris''s call that the criteria are the story''s measure.', 1, 0);
