INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M31W9KVNWYHZ6KZ6W4936QQ2', '01M31VPRD3E401NFE9H3F0ECB6', 'epic', 2, 'The requirement coverage claim takes a boolean', 'complete', NULL, 2, 0);
INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M31W9NKPG8CXW26P1VECC40Y', '01M31VPTGAH0SDJHZKT7XRTVMC', 'epic', 1, 'Retire an observation', 'complete', 'Delivered without new code, on Chris''s decision at the gate. Both criteria hold against the surface as it stands — `update_observation` carries the withdrawal and `list_observation` omits withdrawn rows — so the story''s work was the assertion rather than a second verb doing what the first already does. Task 1 is withdrawn and records the two gaps a verb would have closed.', 1, 0);
